// RF 09: validar que la pregunta exista y no este vacia.
const body = $json.body ?? {};
const pregunta = typeof body.pregunta === 'string' ? body.pregunta.trim() : '';

return [{
  json: {
    consultaId: body.consultaId ?? null,
    pregunta,
    nivelExperiencia: body.nivelExperiencia ?? 'No indicado',
    areaInteres: body.areaInteres ?? 'No indicada',
    valida: pregunta.length > 0
  }
}];

// RF 09: comprobar que el proveedor entrego un vector valido.
const vector = $json.data?.[0]?.embedding;
if (!Array.isArray(vector) || vector.length !== 1536) {
  throw new Error('OpenRouter no devolvió un embedding válido para la pregunta');
}
return [{ json: { vector } }];

// RF 11: umbral minimo de similitud (score coseno de Qdrant).
// Por debajo de este valor el curso se considera irrelevante y NO se envia al modelo.
// Calibrado con pruebas reales (ver docs/calibracion_umbral.md):
// relevantes >= 0.47, no relacionados <= 0.41, fuera del dominio <= 0.31.
const UMBRAL = 0.45;

const entrada = $('Validar entrada').first().json;
const puntos = $json.result?.points ?? [];
const niveles = { BASICO: 'Básico', INTERMEDIO: 'Intermedio', AVANZADO: 'Avanzado' };
const redondear = n => Math.round(n * 10000) / 10000;

// Todos los candidatos con su score: sirve para calibrar el umbral y para la sustentacion
const candidatos = puntos.map(p => ({
  cursoId: Number(p.payload?.curso_id ?? p.id),
  nombre: p.payload?.nombre,
  similitud: redondear(p.score),
  superaUmbral: p.score >= UMBRAL
}));

// RF 10: solo cursos activos y ordenados por relevancia (Qdrant ya los devuelve ordenados)
const fuentes = puntos
  .filter(p => p.score >= UMBRAL && p.payload?.activo === true)
  .map((p, i) => ({
    posicion: i + 1,
    cursoId: Number(p.payload.curso_id ?? p.id),
    nombre: p.payload.nombre,
    descripcion: p.payload.descripcion,
    categoria: p.payload.categoria,
    nivel: p.payload.nivel,
    duracionHoras: p.payload.duracion_horas,
    similitud: redondear(p.score)
  }));

// RF 12: construccion del contexto RAG
const contexto = fuentes.map(f =>
  `${f.posicion}. ${f.nombre}\n` +
  `   Categoría: ${f.categoria} | Nivel: ${niveles[f.nivel] ?? f.nivel} | Duración: ${f.duracionHoras} horas | Similitud: ${f.similitud}\n` +
  `   Descripción: ${f.descripcion}`
).join('\n\n');

const systemPrompt = [
  'Eres el asistente académico de RutaIA y recomiendas cursos de la institución a estudiantes.',
  'Reglas estrictas:',
  '1. Usa ÚNICAMENTE los cursos que aparecen en el CONTEXTO. No inventes cursos, temas ni datos que no estén allí.',
  '2. Menciona cada curso con su nombre exacto, tal como aparece en el contexto.',
  '3. Recomienda solo los cursos que realmente respondan a la necesidad; no es obligatorio mencionarlos todos.',
  '4. Si los cursos del contexto no cubren bien la necesidad del estudiante, reconócelo con honestidad en lugar de forzar la recomendación.',
  '5. La necesidad del estudiante es lo más importante. El nivel de experiencia sirve para sugerir por cuál curso empezar y en qué orden continuar; el área de interés es solo contexto y no debe desviar la recomendación hacia otros temas.',
  '6. No recomiendes recursos, plataformas ni cursos externos a la institución.',
  '7. Responde en español, con un tono cercano y claro, en máximo 180 palabras.'
].join('\n');

const userPrompt =
  `Perfil del estudiante: nivel de experiencia ${entrada.nivelExperiencia}, área de interés ${entrada.areaInteres}.\n` +
  `Necesidad del estudiante: "${entrada.pregunta}"\n\n` +
  `CONTEXTO (cursos recuperados, ordenados por relevancia):\n${contexto}\n\n` +
  'Escribe la recomendación para este estudiante.';

return [{
  json: {
    ...entrada,
    umbral: UMBRAL,
    hayResultados: fuentes.length > 0,
    fuentes,
    candidatos,
    systemPrompt,
    userPrompt
  }
}];

// RF 13: respuesta final con pregunta, recomendacion, fuentes, similitudes y estado.
const datos = $('Aplicar umbral').first().json;
const texto = $json.choices?.[0]?.message?.content?.trim();

if (!texto) {
  throw new Error('El modelo de lenguaje no devolvió una respuesta');
}

return [{
  json: {
    consultaId: datos.consultaId,
    pregunta: datos.pregunta,
    estado: 'RESPONDIDA',
    respuesta: texto,
    fuentes: datos.fuentes,
    busqueda: { umbral: datos.umbral, candidatos: datos.candidatos }
  }
}];
